message.content:
{
  "description": "The creature is a four-legged hybrid standing in right-facing profile on a small patch of dry ground with sparse grass. It has the overall shape, shaggy fur, head, and hooves of a brown goat combined with the domed, segmented shell and scaly leg armor of a turtle or tortoise. The body is covered in long brown fur with a lighter cream underbelly and a thick shaggy ruff around the neck and chest, a bearded goat head with curved horns on top, and a large brown domed shell covering the entire back from shoulders to hips, with matching brown scaly plates wrapping the upper portions of all four legs above the furry lower legs and cloven hooves.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a goat head at the front of the body, covered in short brown fur with a lighter muzzle, a long beard of hair under the chin, a dark eye, and a goat nose and mouth, facing to the right"
    ,
      "where": "at the front end of the body on top of the shaggy neck"
    },
    {
      "part": "horns",
      "looks_like": "two thick, ridged, brown horns that curve backward and slightly outward, with visible growth rings",
      "where": "on top of the head behind the ears"
    },
    {
      "part": "ears",
      "looks_like": "two pointed, upright, fur-covered ears with inner detail",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "thick, long, shaggy brown fur forming a ruff around the neck and chest and continuing as medium-long fur over the body, with a lighter cream-colored patch on the belly",
      "where": "around the neck, chest, sides and belly, and on the hindquarters"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, columnar legs with furry lower sections and upper sections encased in overlapping brown turtle-like scutes",
      "where": "under the body, two front legs under the chest and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "cloven hooves, brown with two toes and visible nails, with short fur above",
      "where": "at the bottom tip of each of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, hairy, brown tail with longer fur hanging down",
      "where": "at the rear end of the body behind the shell and above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large domed turtle/tortoise shell with segmented polygonal scutes in brown and dark brown, each scute with a raised pyramidal center and concentric growth lines",
      "where": "covering the entire back from just behind the shoulders to just in front of the tail"
    },
    {
      "part": "plates",
      "looks_like": "overlapping, polygonal, brown scaly plates with raised centers and growth lines, matching the shell texture",
      "where": "wrapping around the upper thigh and shoulder portions of all four legs"
    },
    {
      "part": "scales",
      "looks_like": "the same brown, hard, polygonal scales that make up the shell and leg plates, with a scaly reptilian texture",
      "where": "on the shell on the back and on the armor covering the upper parts of the legs"
    }
  ],
  "attached_objects": [],
  "animals": ["goat", "turtle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
